function standoutsFor(rows){let profiles=rows.filter(finish).map(r=>({r,parts:pairs(r)})).filter(p=>p.parts.length>=2),all=profiles.flatMap(x=>x.parts.map(s=>({...s,r:x.r,rel:s.seconds/s.km/(x.r.finish_seconds/S.race.nominal_km)})));let categories=[];if(all.length){categories.push({title:'Snabbast relativt eget snitt',list:all.filter(x=>num(x.rel)).sort((a,b)=>a.rel-b.rel).map(x=>({r:x.r,value:(100/Math.max(.0001,x.rel)).toFixed(0)+' % · '+x.to.name,score:x.rel}))});let finishList=profiles.map(x=>{let p=x.parts[x.parts.length-1];return p&&num(p.placeFrom)&&num(p.placeTo)?{r:x.r,p,change:p.placeFrom-p.placeTo}:null}).filter(Boolean);categories.push({title:'Starkaste avslutningen',list:finishList.sort((a,b)=>b.change-a.change).map(x=>({r:x.r,value:(x.change>=0?'+':'')+x.change+' platser',score:-x.change}))});let gains=all.filter(x=>num(x.placeFrom)&&num(x.placeTo)).map(x=>({...x,change:x.placeFrom-x.placeTo}));categories.push({title:'Största placeringslyftet',list:gains.sort((a,b)=>b.change-a.change).map(x=>({r:x.r,value:'+'+x.change+' · '+x.to.name,score:-x.change}))});let even=profiles.map(x=>{let z=x.parts.map(p=>p.seconds/p.km),avg=z.reduce((a,b)=>a+b,0)/z.length;return {r:x.r,cv:Math.sqrt(z.reduce((a,b)=>a+(b-avg)**2,0)/z.length)/avg}}).filter(x=>num(x.cv));categories.push({title:'Jämnast observerade pacing',list:even.sort((a,b)=>a.cv-b.cv).map(x=>({r:x.r,value:(100*x.cv).toFixed(1)+' % variation',score:x.cv}))});let last=profiles.map(x=>{let p=x.parts.at(-1);return p?{r:x.r,sec:p.seconds,km:p.km,name:p.to.name}:null}).filter(Boolean);categories.push({title:'Snabbast på sista verifierade segmentet',list:last.sort((a,b)=>a.sec/a.km-b.sec/b.km).map(x=>({r:x.r,value:pace(x.sec,x.km,S.unit),score:x.sec/x.km}))});}return categories}
